using Aspire.Hosting.Testing;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads evaluation scenarios from evaluation.yml and provides the app host for testing.
/// </summary>
public sealed class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public DistributedApplication App => _app ?? throw new InvalidOperationException("Harness not initialized.");

    public EvaluationConfig Config { get; private set; } = new();

    public async ValueTask InitializeAsync()
    {
        Config = LoadConfig();

        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static EvaluationConfig LoadConfig()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "evaluation.yml");
        if (!File.Exists(path))
        {
            throw new FileNotFoundException("evaluation.yml not found in output directory.", path);
        }

        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(HyphenatedNamingConvention.Instance)
            .IgnoreUnmatchedProperties()
            .Build();

        return deserializer.Deserialize<EvaluationConfig>(yaml);
    }
}

using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Runs the evaluation scenarios defined in evaluation.yml against the app host.
/// </summary>
public sealed class EvaluationTests : IClassFixture<EvaluationHarness>
{
    private readonly EvaluationHarness _harness;

    public EvaluationTests(EvaluationHarness harness)
    {
        _harness = harness;
    }

    [Fact]
    public void ConfigLoadsSuccessfully()
    {
        Assert.NotNull(_harness.Config);
        Assert.NotEmpty(_harness.Config.Scenarios);
    }

    [Fact]
    public void AllScenariosHaveSteps()
    {
        foreach (var scenario in _harness.Config.Scenarios)
        {
            Assert.False(string.IsNullOrWhiteSpace(scenario.Name), "Scenario must have a name.");
            Assert.NotEmpty(scenario.Steps);
        }
    }

    [Fact]
    public void AppHostStartsSuccessfully()
    {
        // If we reach here, the harness initialized the app host without error.
        Assert.NotNull(_harness.App);
    }

    [Fact]
    public async Task BasicHealthScenario()
    {
        var scenario = _harness.Config.Scenarios
            .FirstOrDefault(s => s.Name == "basic-health");

        Assert.NotNull(scenario);

        // The app host is already running via the harness; validate it is healthy.
        var model = _harness.App.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();
        Assert.NotNull(model);
    }
}

