using Aspire.Hosting.Testing;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads evaluation scenarios from evaluation.yml and provides the app host for testing.
/// </summary>
public sealed class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public DistributedApplication App => _app ?? throw new InvalidOperationException("Harness not initialized.");

    public EvaluationConfig Config { get; private set; } = new();

    public async ValueTask InitializeAsync()
    {
        Config = LoadConfig();

        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    private static EvaluationConfig LoadConfig()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "evaluation.yml");
        if (!File.Exists(path))
        {
            throw new FileNotFoundException("evaluation.yml not found in output directory.", path);
        }

        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(HyphenatedNamingConvention.Instance)
            .IgnoreUnmatchedProperties()
            .Build();

        return deserializer.Deserialize<EvaluationConfig>(yaml);
    }
}

